// paths before it commits, as guard does for the repositories.
func queueVcardReferences(u *repox.Unit, m *vcardv1.Vcard, paths []string) {
}

// queueVcardDelete makes u consult name's referrers before it commits
// and publish the NOTIFY event after, as guard does for Delete.
func queueVcardDelete(u *repox.Unit, name string, purged bool) {
	refs := u.Conn().References
	if refs == nil {
		return
	}
	var check *repox.DeleteCheck
	u.Before(func(ctx context.Context) (err error) {
		check, err = refs.CheckDelete(ctx, "the-protobuf-project.org/Vcard", name)
		return err
	})
	u.After(func(ctx context.Context) { check.Done(ctx, purged) })
}

// queueVcardPurge makes u ask name's referrers before it commits; the
// purge it queues keeps the row when *keep is true.
func queueVcardPurge(u *repox.Unit, name string) (keep *bool) {
	keep = new(bool)
	if refs := u.Conn().References; refs != nil {
		u.Before(func(ctx context.Context) error {
			*keep = refs.KeepOnPurge(ctx, "the-protobuf-project.org/Vcard", name)
			return nil
		})
	}
	return keep
}
